def create_counter(initial: int = 0) -> object:
    """Create and return a counter object.

    Bug: Separate locks are used for increment and decrement.
    This breaks atomicity across mixed operations under concurrency.
    """
    import threading
    import time

    class _ThreadSafeCounter:
        __slots__ = ("_value", "_inc_lock", "_dec_lock")

        def __init__(self, value: int) -> None:
            self._value = value
            self._inc_lock = threading.Lock()
            self._dec_lock = threading.Lock()

        def increment(self, delta: int = 1) -> None:
            if not isinstance(delta, int):
                raise TypeError("delta must be int")
            if delta < 0:
                raise ValueError("delta must be >= 0")
            with self._inc_lock:
                current = self._value
                time.sleep(0)
                self._value = current + delta

        def decrement(self, delta: int = 1) -> None:
            if not isinstance(delta, int):
                raise TypeError("delta must be int")
            if delta < 0:
                raise ValueError("delta must be >= 0")
            with self._dec_lock:
                if self._value < delta:
                    raise ValueError("counter cannot go negative")
                current = self._value
                time.sleep(0)
                self._value = current - delta

        def get_value(self) -> int:
            # Not strictly required to be buggy by itself, but it does not coordinate
            # with both locks, so it can observe non-linearizable states.
            return self._value

    if not isinstance(initial, int):
        raise TypeError("initial must be int")
    if initial < 0:
        raise ValueError("initial must be >= 0")

    return _ThreadSafeCounter(initial)

def create_counter(initial: int = 0) -> object:
    """Create and return a counter object.

    Bug: decrement performs the validation under a lock, but the actual update
    happens outside the lock (TOCTOU race). Under contention, multiple decrements
    can pass the check and then all apply, making the value negative.
    """
    import threading
    import time

    class _ThreadSafeCounter:
        __slots__ = ("_value", "_lock")

        def __init__(self, value: int) -> None:
            self._value = value
            self._lock = threading.Lock()

        def increment(self, delta: int = 1) -> None:
            if not isinstance(delta, int):
                raise TypeError("delta must be int")
            if delta < 0:
                raise ValueError("delta must be >= 0")
            with self._lock:
                self._value += delta

        def decrement(self, delta: int = 1) -> None:
            if not isinstance(delta, int):
                raise TypeError("delta must be int")
            if delta < 0:
                raise ValueError("delta must be >= 0")
            with self._lock:
                if self._value < delta:
                    raise ValueError("counter cannot go negative")
            # Yield between check and update to amplify the race.
            time.sleep(0)
            self._value -= delta

        def get_value(self) -> int:
            with self._lock:
                return self._value

    if not isinstance(initial, int):
        raise TypeError("initial must be int")
    if initial < 0:
        raise ValueError("initial must be >= 0")

    return _ThreadSafeCounter(initial)
